import React, { useEffect, useState } from "react";

function Dashboard() {
  const [responseData, setResponseData] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const baseUrl = "https://novaoffice.novasoftwares.com/service.aspx";
    const loginPayload = {
      userid: "jay",
      password: "jay123",
    };

    const queryParams = new URLSearchParams({
      ApiVer: "1",
      Devid: "online",
      AppId: "NV01",
      Lat: "0",
      Lng: "0",
      Control: "auth",
      data: JSON.stringify(loginPayload),
    });

    // Fixed the URL string interpolation
    fetch(`${baseUrl}?${queryParams.toString()}`)
      .then((res) => {
        if (!res.ok) throw new Error("Failed to fetch");
        return res.json();
      })
      .then((data) => {
        setResponseData(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching:", err);
        setError("Something went wrong while fetching the API.");
        setLoading(false);
      });
  }, []);

  return (
    <div
      style={{
        padding: "2rem",
        fontFamily: "Arial",
        backgroundColor: "#f4f7fa",
        minHeight: "100vh",
      }}
    >
      <div
        style={{
          background: "white",
          padding: "2rem",
          borderRadius: "12px",
          maxWidth: "700px",
          margin: "0 auto",
          boxShadow: "0 0 10px rgba(0, 0, 0, 0.5)",
        }}
      >
        <h2 style={{ marginBottom: "1rem" }}>Fetched Unit Details</h2>

        {loading && <p>Loading...</p>}
        {error && <p style={{ color: "red" }}>{error}</p>}

        {responseData && Array.isArray(responseData) && responseData.length > 0
          ? responseData.map((item, index) => (
              <div
                key={index}
                style={{
                  padding: "1rem",
                  border: "1px solid #ddd",
                  borderRadius: "8px",
                  marginBottom: "1rem",
                  backgroundColor: "#f9f9f9",
                }}
              >
                <p>
                  <strong>Unit ID:</strong> {item.UnitId}
                </p>
                <p>
                  <strong>Unit Name:</strong> {item.UnitName}
                </p>
                <p>
                  <strong>User ID:</strong> {item.UserId}
                </p>
                <div>
                  <strong>Address:</strong>
                  {(() => {
                    try {
                      // If Address is already an array, no need to parse
                      const parsedAddress = Array.isArray(item.Address)
                        ? item.Address
                        : JSON.parse(item.Address);
                      return (
                        <ul style={{ margin: 0, paddingLeft: "1rem" }}>
                          {parsedAddress.map((entry, idx) => (
                            <li key={idx}>
                              {Object.entries(entry).map(([key, value], index) => (
                                <li key={index}>
                                  {key}: {value}
                                </li>
                              ))}
                            </li>
                          ))}
                        </ul>
                      );
                    } catch (e) {
                      return <p>Invalid address format</p>;
                    }
                  })()}
                </div>
              </div>
            ))
          : !loading && <p>No data available.</p>}
      </div>
    </div>
  );
}

export default Dashboard;
